<div class="page-title"><div><em>INBOX</em><h1>Notifications</h1><p>Updates about your account and activity.</p></div><form method="post" action="<?=site_url('notifications')?>"><button class="outline">Mark all as read</button></form></div><?php if(!$notifs):?><div class="empty">You have no notifications yet.</div><?php endif?><section class="panel list"><?php foreach($notifs as $n):?><div class="list-row notif-row <?=$n['is_read']?'':'unread'?>"><?php $icons=array('transfer'=>'↗','ticket'=>'?','security'=>'✓','loan'=>'▥','card'=>'▤','deposit'=>'↓','general'=>'♢');?><span class="avatar"><?=$icons[$n['type']]??'♢'?></span><div><b><?=html_escape($n['title'])?></b><small><?=html_escape($n['body'])?> · <?=date('M j, g:i a',strtotime($n['created_at']))?></small></div><?php if($n['link']):?><a class="outline" href="<?=site_url($n['link'])?>">View</a><?php endif?></div><?php endforeach?></section>
